<?php&#10;&#10;namespace App\Notifications;&#10;&#10;use App\Models\Resume;&#10;use Illuminate\Bus\Queueable;&#10;use Illuminate\Notifications\Messages\MailMessage;&#10;use Illuminate\Notifications\Notification;&#10;&#10;class CvReviewNotification extends Notification&#10;{&#10;    use Queueable;&#10;&#10;    public function __construct(public Resume $resume) {}&#10;&#10;    public function via($notifiable): array&#10;    {&#10;        return ['database', 'mail'];&#10;    }&#10;&#10;    public function toArray($notifiable): array&#10;    {&#10;        $status = $this->resume->status === 'approved' ? 'approved' : 'rejected';&#10;        return [&#10;            'title' => "Your CV has been {$status}",&#10;            'message' => $this->resume->feedback,&#10;            'resume_id' => $this->resume->id,&#10;            'status' => $status,&#10;        ];&#10;    }&#10;&#10;    public function toMail($notifiable): MailMessage&#10;    {&#10;        $status = $this->resume->status === 'approved' ? 'approved' : 'rejected';&#10;        return (new MailMessage)&#10;                    ->subject("Your CV has been {$status}")&#10;                    ->line("Your CV '{$this->resume->title}' has been {$status}.")&#10;                    ->line('Feedback: ' . $this->resume->feedback)&#10;                    ->action('View CVs', route('cv'));&#10;    }&#10;}
